 static Matrix4x4 Homography(Vector2[]from,Vector2[]to){double[,]a=new double[8,9];for(int k=0;k<4;k++){double x=from[k].x,y=from[k].y,u=to[k].x,v=to[k].y;int i=k*2;a[i,0]=x;a[i,1]=y;a[i,2]=1;a[i,6]=-u*x;a[i,7]=-u*y;a[i,8]=u;a[i+1,3]=x;a[i+1,4]=y;a[i+1,5]=1;a[i+1,6]=-v*x;a[i+1,7]=-v*y;a[i+1,8]=v;}for(int col=0;col<8;col++){int pivot=col;for(int k=col+1;k<8;k++)if(Math.Abs(a[k,col])>Math.Abs(a[pivot,col]))pivot=k;if(Math.Abs(a[pivot,col])<1e-10)throw new Exception("Unsupported edge-on eye basis");for(int k=col;k<9;k++)(a[col,k],a[pivot,k])=(a[pivot,k],a[col,k]);double value=a[col,col];for(int k=col;k<9;k++)a[col,k]/=value;for(int row=0;row<8;row++)if(row!=col){value=a[row,col];for(int k=col;k<9;k++)a[row,k]-=a[col,k]*value;}}var m=Matrix4x4.zero;m.SetRow(0,new Vector4((float)a[0,8],(float)a[1,8],(float)a[2,8],0));m.SetRow(1,new Vector4((float)a[3,8],(float)a[4,8],(float)a[5,8],0));m.SetRow(2,new Vector4((float)a[6,8],(float)a[7,8],1,0));return m;}
